import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-join-class',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './join-class.component.html',
  styleUrls: ['./join-class.component.scss']
})
export class JoinClassComponent {
  code = '';
  classData: any = null;
  loading = false;
  msg = '';

  constructor(private profService: ProfService) {}

  join() {
    if (!this.code.trim()) {
      this.msg = '⚠️ Code requis';
      return;
    }

    this.loading = true;
    this.profService.getClassByCode(this.code).subscribe({
      next: res => {
        this.classData = res;
        this.loading = false;
        this.msg = '';
      },
      error: err => {
        console.error('Erreur recherche classe:', err);
        this.msg = '❌ Classe introuvable';
        this.loading = false;
        this.classData = null;
      }
    });
  }
}
